                           ("--exclude-tag", exclude_tags)):
            while flag in argv:
                i = argv.index(flag)
                try:
                    sink.append(argv[i + 1])
                except IndexError:
                    print(f"ERROR: {flag} needs a value", file=sys.stderr)
                    return 2
                del argv[i:i + 2]
    if len(tags) > 1:
